// Abre 1 item por canal ligado; no WhatsApp, 1 item por PARTE (whatsapp_partes: texto acima de ~4.000 caracteres dividido entre parágrafos pelo Place Sprints) e no
// Discord (canal INTERNO da equipe) 1 item por parte de discord_partes (≤ 1.900 caracteres cada), sempre na ordem; o Discord leva as menções permitidas (mencionar/mencionar_cargos).
// O texto já chega auditado do Place Sprints; aqui não se decide conteúdo. E-mail recebe o texto inteiro.
const lote = $input.first().json.body ?? $input.first().json;
const out = [];
for (const [canal, c] of Object.entries(lote.canais || {})) if (c && c.ligado && c.destino) {
  const partes = canal === 'whatsapp' && Array.isArray(lote.whatsapp_partes) && lote.whatsapp_partes.length ? lote.whatsapp_partes
    : canal === 'discord' && Array.isArray(lote.discord_partes) && lote.discord_partes.length ? lote.discord_partes : [lote.texto || ''];
  partes.forEach((texto, k) => out.push({ json: { canal, lote_id: lote.lote_id, cliente_rotulo: lote.cliente_rotulo || '', tipo: lote.tipo || '', interno: !!lote.interno, assunto: lote.assunto || 'Place2u · aviso', texto, texto_html: lote.texto_html || '', destino: c.destino, link: lote.link || '', parte: k + 1, partes: partes.length,
    mencionar: lote.discord_mencionar || [], mencionar_cargos: lote.discord_mencionar_cargos || [] } }));
}
return out;

// Sem credencial SMTP: devolve 503 para o recibo sair 'falhou' (nunca 'entregue'). Para ligar o e-mail: crie a credencial SMTP e troque este nó por um «Send Email»
// (de: avisos@place2u.com.br, para: {{ $json.destino }}, assunto: {{ $json.assunto }}, HTML: {{ $json.texto_html }}), mantendo «On Error: Continue».
return $input.all().map(() => ({ json: { statusCode: 503 } }));

// Recibo por canal: só estado e carimbo; nunca o corpo da resposta do provedor.
// Modo «Run Once for All Items»: o item de origem é lido por itemMatching(idx).
// WhatsApp em partes: UM recibo por (lote, canal) — entregue só se TODAS as partes saíram (a 1ª entregue não esconde a 2ª que falhou).
// Teste de canal (tipo 'teste') e incidente do vigia/saúde (tipo 'incidente', autogestão) não têm lote no Place Sprints: não geram recibo (senão o recibo volta 422 e a execução fica como erro).
const por = new Map();
$input.all().forEach((i, idx) => { const o = $('Abrir por canal').itemMatching(idx).json; if (o.tipo === 'teste' || o.tipo === 'incidente') return; const sc = i.json.statusCode ?? (i.json.error ? 500 : 200); const k = o.lote_id + '|' + o.canal; const a = por.get(k) || { lote_id: o.lote_id, canal: o.canal, ok: true, status: sc }; if (sc >= 300) { a.ok = false; a.status = sc } por.set(k, a) });
return [...por.values()].map(a => ({ json: { lote_id: a.lote_id, canal: a.canal, estado: a.ok ? 'entregue' : 'falhou', status: a.status, em: new Date().toISOString() } }));
